        "sourceMarkdown": "### C01-03 — то же\n\nЯ знал о Елене ТО(ЖЕ), что и остальные соседи, поэтому не мог добавить ничего важного.\n\n**Нормативное написание:** то же. **Тип:** раздельно.\n\n**Грамматика:** Указательное местоимение то в винительном падеже + частица же.\n\n**Объяснение:** Знал что? — то же. Местоимение является дополнением, а придаточная часть что и остальные соседи раскрывает его содержание. Же подчёркивает тождество известной информации и пишется отдельно.\n\n**Дистрактор C01.B:** Слить то же, не заметив предметного указания, роли дополнения или определения. Правильная стратегия: Найти синтаксическую роль то; учесть тождество, самое и поясняющее что.\n\n**Различие контекста:** Тождество сведений; то — дополнение с последующим что.\n\n**Источник:** d50, вариант 5, предложение 4 (d50-v05-p4).\n\n**Прослеживаемость:** `ege14-raw-061574b412e96a429fb035b349024768326f575d2c7130966066ca2887553b61:4`; `research/stage1/classified_batch_01_v2.json#/records/3/contexts/3`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (ПО)ЭТОМУ → поэтому. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php).",
