        "sourceMarkdown": "### C02-02 — также\n\nВ разговоре люди ведут себя по-разному — в зависимости от темы, а ТАК(ЖЕ) от мотива и цели общения.\n\n**Нормативное написание:** также. **Тип:** слитно.\n\n**Грамматика:** Компонент соединительного союза а также.\n\n**Объяснение:** Союз добавляет ещё одно основание поведения: зависимость не только от темы, но и от мотива и цели. Также связывает однородные предложные группы, а не обозначает одинаковый способ действия.\n\n**Дистрактор C02.A:** Разделить также в однородном ряду из-за сходства с так же. Правильная стратегия: Проверить, что а также связывает однородные компоненты, а так не является обстоятельством.\n\n**Различие контекста:** Присоединение однородных зависимых групп.\n\n**Источник:** d36, вариант 14, предложение 5 (d36-v14-p5).\n\n**Прослеживаемость:** `ege14-raw-acc9c223dd685f589ce9e838909f5ee034a842ac69df91af0347824660df390f:17`; `research/stage1/classified_batch_01_v2.json#/records/29/contexts/16`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (ПО)РАЗНОМУ → по-разному. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php); [N08: Грамота.ру. Справочник по пунктуации: «Так же как (и)»](https://gramota.ru/biblioteka/spravochniki/spravochnik-po-punktuatsii/tak-zhe-kak-i).",
