        "sourceMarkdown": "### C02-03 — так же\n\nСегодня было ТАК(ЖЕ) душно, как и вчера, и завтра будет то же самое.\n\n**Нормативное написание:** так же. **Тип:** раздельно.\n\n**Грамматика:** Местоименное наречие так + усилительная частица же.\n\n**Объяснение:** Так относится к степени признака душно; как и вчера задаёт меру сравнения. Это обстоятельственное слово с отдельной частицей же, а не присоединительный союз.\n\n**Дистрактор C02.B:** Считать одинаковый способ/степень действия добавочным сообщением. Правильная стратегия: Отличить обстоятельственное так с же и сравнительное союзное сочетание от добавочного также.\n\n**Дистрактор C02.C:** Писать раздельно только при соседнем как либо сливать любой союз. Правильная стратегия: Сопоставить явное сравнение, составной сравнительный союз и сравнение без ближайшего как; форма слова не выводится из одного маркера.\n\n**Различие контекста:** Сравнение степени признака, явное как.\n\n**Источник:** d50, вариант 4, предложение 2 (d50-v04-p2).\n\n**Прослеживаемость:** `ege14-raw-acc9c223dd685f589ce9e838909f5ee034a842ac69df91af0347824660df390f:1`; `research/stage1/classified_batch_01_v2.json#/records/29/contexts/0`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** ТО(ЖЕ) → то же. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php); [N08: Грамота.ру. Справочник по пунктуации: «Так же как (и)»](https://gramota.ru/biblioteka/spravochniki/spravochnik-po-punktuatsii/tak-zhe-kak-i).",
