        "sourceMarkdown": "### C03-01 — чтобы\n\nЧТО(БЫ) ощутить хоть какое-то присутствие родного человека, Виталий часто перечитывал письма.\n\n**Нормативное написание:** чтобы. **Тип:** слитно.\n\n**Грамматика:** Подчинительный союз цели.\n\n**Объяснение:** Придаточная инфинитивная часть указывает цель перечитывания писем. Чтобы вводит всю часть и не занимает позицию члена предложения; объект при ощутить уже выражен сочетанием присутствие родного человека. Союз пишется слитно.\n\n**Дистрактор C03.A:** Писать что бы при цели, механически выделив частицу бы. Правильная стратегия: Определить цель всей придаточной части; у что нет собственной позиции члена предложения.\n\n**Различие контекста:** Цель перед главным предложением; личная память.\n\n**Источник:** d50, вариант 11, предложение 1 (d50-v11-p1).\n\n**Прослеживаемость:** `ege14-raw-ac9dd1e355bb837d5319ade3c0433ba105d1afd75992d88e2fda2345bc77705a:2`; `research/stage1/classified_batch_03.json#/records/12/contexts/1`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** КАКОЕ(ТО) → какое-то. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php).",
