        "sourceMarkdown": "### C03-03 — чтобы\n\nЕму в голову не может прийти, ЧТО(БЫ) кто-нибудь его заметил или занялся им.\n\n**Нормативное написание:** чтобы. **Тип:** слитно.\n\n**Грамматика:** Подчинительный изъяснительный союз.\n\n**Объяснение:** Придаточная часть раскрывает содержание того, что не может прийти ему в голову: возможность чужого внимания. У союза нет предметной роли; его нельзя заменять вопросительным что. Поэтому написание слитное и без значения цели.\n\n**Дистрактор C03.B:** Считать, что чтобы бывает только союзом цели. Правильная стратегия: Увидеть изъяснительную связь после просьбы/мысли; отсутствие цели не означает раздельности.\n\n**Различие контекста:** Изъяснение при отрицании возможности мысли.\n\n**Источник:** d36, вариант 24, предложение 2 (d36-v24-p2).\n\n**Прослеживаемость:** `ege14-raw-ac9dd1e355bb837d5319ade3c0433ba105d1afd75992d88e2fda2345bc77705a:36`; `research/stage1/classified_batch_03.json#/records/12/contexts/35`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** КТО(НИБУДЬ) → кто-нибудь. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php).",
