        "sourceMarkdown": "### C03-05 — что бы\n\nЧТО(БЫ) вы уточнили в методике исследования, если бы получили доступ к архиву?\n\n**Нормативное написание:** что бы. **Тип:** раздельно.\n\n**Грамматика:** Вопросительное местоимение что + частица бы.\n\n**Объяснение:** Уточнить что? — вопрос о содержании уточнения. Что занимает позицию дополнения; бы относится к предполагаемому действию. При перестановке получается вы бы уточнили что, но решающим остаётся предметный вопрос.\n\n**Дистрактор C03.C:** Слить что бы в прямом или косвенном вопросе. Правильная стратегия: Установить предмет вопроса и роль местоимения как дополнения; бы выражает предположительность.\n\n**Различие контекста:** Прямой вопрос об изменении исследования.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php).",
