        "sourceMarkdown": "### C03-07 — что бы\n\nЧТО(БЫ) ни говорили другие, я считаю, что человек сам вправе распоряжаться своим будущим.\n\n**Нормативное написание:** что бы. **Тип:** раздельно.\n\n**Грамматика:** Относительное местоимение что + частица бы; уступительная конструкция что бы ни.\n\n**Объяснение:** Говорили что? — что занимает место дополнения. Сочетание с бы и ни создаёт обобщённую уступку: любое чужое мнение не меняет главного утверждения. Бы остаётся отдельным словом, несмотря на связь придаточной части с главной.\n\n**Дистрактор C03.D:** Слить что бы ни, потому что сочетание связывает части сложного предложения. Правильная стратегия: Проверить самостоятельную роль что — дополнение или подлежащее — в обобщённой уступке.\n\n**Различие контекста:** Уступка; местоимение в функции дополнения.\n\n**Источник:** d50, вариант 10, предложение 5 (d50-v10-p5).\n\n**Прослеживаемость:** `ege14-raw-ac9dd1e355bb837d5319ade3c0433ba105d1afd75992d88e2fda2345bc77705a:1`; `research/stage1/classified_batch_03.json#/records/12/contexts/0`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (В)ПРАВЕ → вправе. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php).",
