        "sourceMarkdown": "### C04-03 — за то\n\nВ своих поступках он был по-прежнему неосмотрительным, (ЗА)ТО и поплатился.\n\n**Нормативное написание:** за то. **Тип:** раздельно.\n\n**Грамматика:** Предлог за + указательное местоимение то в винительном падеже.\n\n**Объяснение:** Поплатился за что? — за то, то есть за неосмотрительность. Местоимение отсылает к первой части и зависит от глагола поплатился; предлог пишется отдельно. Наличие запятой между частями не делает сочетание союзом.\n\n**Дистрактор C04.B:** Слить за то по одному положению после запятой или перед что. Правильная стратегия: Найти управление поплатиться/осуждать за что; то сохраняет предметное указание.\n\n**Различие контекста:** Указание на причину последствия без последующего что.\n\n**Источник:** d50, вариант 4, предложение 1 (d50-v04-p1).\n\n**Прослеживаемость:** `ege14-raw-a9e55cf795a57c72479889b08e388c3f3f8de5a329afb3c7a5acb8658f8e816c:1`; `research/stage1/classified_batch_01_v2.json#/records/28/contexts/0`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (ПО)ПРЕЖНЕМУ → по-прежнему. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php).",
