        "sourceMarkdown": "### C05-04 — при чём\n\nЯ не понимаю, (ПРИ)ЧЁМ здесь мой черновик, если ошибку нашли в опубликованном отчёте.\n\n**Нормативное написание:** при чём. **Тип:** раздельно.\n\n**Грамматика:** Предлог при + относительное местоимение чём в косвенном вопросе.\n\n**Объяснение:** Говорящий не понимает связи своего черновика с ошибкой. Сочетание при чём сохраняет вопрос о причастности внутри придаточной части. Положение между частями предложения не превращает его в присоединительный союз.\n\n**Дистрактор C05.B:** Слить при чём на границе частей, особенно в косвенном вопросе. Правильная стратегия: Сохранить предлог и вопросительно-относительное местоимение при вопросе о причастности.\n\n**Различие контекста:** Косвенный вопрос; граница частей не доказывает союзность.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php).",
