        "sourceMarkdown": "### C06-01 — при том\n\nПРИ(ТОМ) учреждении есть попечительский совет, который много делает, что бы о нём ни говорили.\n\n**Нормативное написание:** при том. **Тип:** раздельно.\n\n**Грамматика:** Предлог при + указательное местоимение том, согласованное с учреждении.\n\n**Объяснение:** Том относится к существительному учреждении и имеет форму предложного падежа. При вводит именную группу со значением организационной связи; местоимение можно заменить на этом. Это не присоединение дополнительного сообщения.\n\n**Дистрактор C06.B:** Слить при том перед именной группой. Правильная стратегия: Определить согласование том с существительным и зависимость группы от предлога при.\n\n**Различие контекста:** Связь совета с учреждением; определяемое существительное.\n\n**Источник:** d36, вариант 21, предложение 1 (d36-v21-p1).\n\n**Прослеживаемость:** `ege14-raw-386ce8cefb30ff7e5627a6901e81e8858e0e98c85e99953f9bf3251e338c036a:2`; `research/stage1/classified_batch_11.json#/records/1/contexts/1`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** ЧТО(БЫ) → что бы. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N04: ИРЯ РАН. Орфографическое комментирование русского словаря: закрепившиеся написания союзов](https://oross.ruslang.ru/orthogr/formula?id=671).",
