        "sourceMarkdown": "### C06-02 — при том\n\n(ПРИ)ТОМ освещении, которое удалось установить в зале, стали видны следы прежней реставрации.\n\n**Нормативное написание:** при том. **Тип:** раздельно.\n\n**Грамматика:** Предлог при + указательное местоимение том в предложном падеже.\n\n**Объяснение:** Том согласовано с освещении; придаточная часть уточняет это освещение. При обозначает условия видимости. Определительная связь с существительным требует отдельного предлога и местоимения.\n\n**Дистрактор C06.B:** Слить при том перед именной группой. Правильная стратегия: Определить согласование том с существительным и зависимость группы от предлога при.\n\n**Различие контекста:** Условия наблюдения; определение раскрыто придаточным.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N04: ИРЯ РАН. Орфографическое комментирование русского словаря: закрепившиеся написания союзов](https://oross.ruslang.ru/orthogr/formula?id=671).",
