        "sourceMarkdown": "### C06-03 — притом\n\nОбъяснение оказалось убедительным и (ПРИ)ТОМ проверяемым на независимом материале.\n\n**Нормативное написание:** притом. **Тип:** слитно.\n\n**Грамматика:** Сочинительный присоединительный союз.\n\n**Объяснение:** Притом присоединяет дополнительную характеристику к убедительным: ещё и проверяемым. После при нет именной группы с указательным том. Значение добавления подтверждает единый союз и слитное написание.\n\n**Дистрактор C06.A:** Разделить присоединительное притом по формальному сходству с при том. Правильная стратегия: Найти присоединение нового свойства или сообщения; не изобретать существительное при том.\n\n**Различие контекста:** Присоединение однородного определения.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N04: ИРЯ РАН. Орфографическое комментирование русского словаря: закрепившиеся написания союзов](https://oross.ruslang.ru/orthogr/formula?id=671).",
