        "sourceMarkdown": "### C07-01 — итак\n\n(И)ТАК, вывод ясен: что бы ни случилось, необходимо собраться с силами и не терять присутствия духа.\n\n**Нормативное написание:** итак. **Тип:** слитно.\n\n**Грамматика:** Итоговый союз в БТС/БУСРЯ; вводное слово в РОС.\n\n**Объяснение:** Итак маркирует итог и переход к сформулированному выводу. Так не относится к отдельному сказуемому как обстоятельство способа или степени. Лексическое написание слитное при обеих словарных квалификациях; запятая — сопутствующий, не единственный признак.\n\n**Дистрактор C07.A:** Разделить итак в итоговом переходе либо считать запятую единственным доказательством. Правильная стратегия: Проверить итоговую связь; наречие так не определяет действие или степень признака.\n\n**Различие контекста:** Итог с явно названным выводом и практическим следствием.\n\n**Источник:** d36, вариант 19, предложение 5 (d36-v19-p5).\n\n**Прослеживаемость:** `ege14-raw-b1eaa4f9da292356a706fda75f0aa9ba0f34d90dbe5247b51f14d968ac5ad987:3`; `research/stage1/classified_batch_03.json#/records/4/contexts/2`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** ЧТО(БЫ) → что бы. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php); [N05: Русский орфографический словарь: статьи итак, хотя бы](https://gramota.ru/storage/public/normdicts/orfograficheskij_slovar.pdf).",
