        "sourceMarkdown": "### C07-03 — и так\n\nИсследователь задержался у витрины (И)ТАК увлёкся чтением старой карты, что не заметил закрытия музея.\n\n**Нормативное написание:** и так. **Тип:** раздельно.\n\n**Грамматика:** Сочинительный союз и + местоименное наречие так.\n\n**Объяснение:** И соединяет сказуемые задержался и увлёкся; так относится к степени увлечения и соотносится с придаточной частью что не заметил. Отдельный союз и не сливается с обстоятельственным так.\n\n**Дистрактор C07.B:** Слить и так в обстоятельственном или усилительном употреблении. Правильная стратегия: Найти самостоятельное так при сказуемом/признаке; отдельно квалифицировать и как союз либо частицу.\n\n**Различие контекста:** Однородные сказуемые; степень действия раскрыта следствием.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php); [N05: Русский орфографический словарь: статьи итак, хотя бы](https://gramota.ru/storage/public/normdicts/orfograficheskij_slovar.pdf).",
