        "sourceMarkdown": "### C08-01 — поскольку\n\nЭксперимент пришлось повторить, (ПО)СКОЛЬКУ один из датчиков вышел из строя.\n\n**Нормативное написание:** поскольку. **Тип:** слитно.\n\n**Грамматика:** Подчинительный причинный союз.\n\n**Объяснение:** Придаточная часть сообщает причину повторения эксперимента: отказ датчика. Поскольку связывает две предикативные части и не занимает в них позицию члена предложения. Количество или распределение предметов не выражено; причинный союз поскольку пишется слитно.\n\n**Дистрактор C08.A:** Разделить поскольку из-за внешнего сходства с количественным вопросом. Правильная стратегия: Установить причинную связь между частями и отсутствие распределяемого количества.\n\n**Различие контекста:** Причина повторного действия после главной части; неисправность измерительного оборудования.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Примечание:** Авторская замена по замечанию преподавателя. Прежний контекст d36-v12-p4 сохранён в исследовательском реестре, истории блока и research_provenance; он больше не является источником учебного предложения C08-01.\n\n**Опора:** [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php); [N06: Грамота.ру, ответ № 318443 от 30.10.2024](https://gramota.ru/spravka/vopros/318443).",
