        "sourceMarkdown": "### C08-04 — по сколько\n\nРуководитель уточнил, (ПО)СКОЛЬКО часов в день участники смогут работать в архиве.\n\n**Нормативное написание:** по сколько. **Тип:** раздельно.\n\n**Грамматика:** Предлог по с распределительным значением + относительное местоименное числительное сколько в косвенном вопросе (форма на -о).\n\n**Объяснение:** Придаточная часть раскрывает содержание уточнения — количество часов работы на каждый день. Сколько входит в количественную группу с часов, а по выражает распределение времени. Это предложно-количественное сочетание, а не причинный союз; по пишется отдельно.\n\n**Дистрактор C08.B:** Слить по сколько в количественном вопросе по аналогии с поскольку; объявить допустимое по скольку ошибкой. Правильная стратегия: Установить распределительный предлог и местоименное числительное; различать раздельность и выбор нормативной формы на -о/-у.\n\n**Различие контекста:** Косвенный количественный вопрос о повторяющемся расписании.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Варианты свободного текста:** по сколько, по скольку. В данных скобках буквы не меняются.\n\n**Примечание:** По решению преподавателя выбрана форма по сколько; допустимая форма по скольку сохранена в исследовательских примечаниях. Для маски (ПО)СКОЛЬКО буквы не меняются, поэтому ответ — по сколько. См. N06 и editorial_changes.md, E03.\n\n**Опора:** [N02: Полный академический справочник под ред. В. В. Лопатина, § 140](https://orthographia.ru/orf.php?paragraph=pp140.php); [N06: Грамота.ру, ответ № 318443 от 30.10.2024](https://gramota.ru/spravka/vopros/318443).",
