        "sourceMarkdown": "### C09-01 — потому что\n\nБрат сдал экзамены досрочно, ПОТОМУ(ЧТО) это было возможно, и через год окончил курс так же хорошо, как и сестра.\n\n**Нормативное написание:** потому что. **Тип:** раздельно.\n\n**Грамматика:** Составной подчинительный причинный союз.\n\n**Объяснение:** Часть объясняет причину досрочной сдачи. Союз состоит из двух слов: потому внутри себя слитно, что отдельно. По тому здесь не выражает зависимой именной группы.\n\n**Дистрактор C09.A:** Слить потому что в одно слово или разбить потому внутри причинного союза. Правильная стратегия: Различать внутреннее слитное потому и пробел перед что в составном союзе.\n\n**Дистрактор C09.E:** Считать любую последовательность по/тому началом причинного союза. Правильная стратегия: Проверить управление по чему и местоименное указание; не переносить написание потому что на свободное по тому.\n\n**Различие контекста:** Причина действия, после которой следует продолжение повествования.\n\n**Источник:** d50, вариант 32, предложение 3 (d50-v32-p3).\n\n**Прослеживаемость:** `ege14-raw-96544eaf12b81825e680f7f492facf715c4a1f3dd37cb979d2fd2a4d1d825663:3`; `research/stage1/classified_batch_05.json#/records/22/contexts/2`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** ТАК(ЖЕ) → так же. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N10: Решения преподавателя](../teacher_decisions.md).",
