        "sourceMarkdown": "### C09-04 — так как\n\nТАК(КАК) ночные заморозки повредили растения, начало полевых наблюдений перенесли на неделю.\n\n**Нормативное написание:** так как. **Тип:** раздельно.\n\n**Грамматика:** Составной причинный союз.\n\n**Объяснение:** Придаточная часть в начале предложения содержит основание переноса наблюдений. Так как связывает части со значением причины и пишется в два слова независимо от позиции.\n\n**Дистрактор C09.B:** Слить так как на основании единой союзной функции. Правильная стратегия: Сохранить два слова в причинном союзе в обеих позициях придаточного.\n\n**Различие контекста:** Причина перед главным предложением; условия наблюдения.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N10: Решения преподавателя](../teacher_decisions.md).",
