        "sourceMarkdown": "### C09-05 — так что\n\nНа градуснике всего четыре градуса выше нуля, ТАК(ЧТО) тем, кто собирается спускаться в глубь моря, следует под гидрокостюм надеть тёплые вещи.\n\n**Нормативное написание:** так что. **Тип:** раздельно.\n\n**Грамматика:** Составной подчинительный союз следствия.\n\n**Объяснение:** Вторая часть выводит практическое следствие из низкой температуры. Так что — два слова; его нельзя заменить присоединительным также без изменения отношения между частями. Нецелевая форма в глубь принята по решению S13, с сохранением допустимого вглубь вне данного упражнения.\n\n**Дистрактор C09.C:** Слить так что по аналогии с также; смешать следствие и добавление. Правильная стратегия: Установить придаточное следствия и сохранить два слова; также — другая лексема и другая связь, а не вариант ключа.\n\n**Различие контекста:** Следствие с практической рекомендацией.\n\n**Источник:** d50, вариант 14, предложение 2 (d50-v14-p2).\n\n**Прослеживаемость:** `ege14-raw-2b2778cd94d8c8b6c48ec62c5ea608336e830bc24f28ed1447255581fe9a6c5b:1`; `research/stage1/classified_batch_04.json#/records/1/contexts/0`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (В)ГЛУБЬ → в глубь. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Примечание:** Нецелевое (В)ГЛУБЬ раскрыто как в глубь согласно решению преподавателя S13. Вглубь здесь также разрешено; этот фрагмент не является проверяемой орфограммой блока.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N10: Решения преподавателя](../teacher_decisions.md).",
