        "sourceMarkdown": "### C09-07 — то есть\n\nАвтор, (ТО)ЕСТЬ я, записывал кое-как, наспех, что записывал, а что и не записывал, слушал развесив уши, забыв про обязанности.\n\n**Нормативное написание:** то есть. **Тип:** раздельно.\n\n**Грамматика:** Сочинительный пояснительный союз.\n\n**Объяснение:** Я уточняет, кто назван автором. То есть связывает два обозначения одного лица; это составной союз из двух слов. В его составе то не является дефисной частицей.\n\n**Дистрактор C09.D:** Слить то есть или присоединить то через дефис. Правильная стратегия: Распознать пояснение и словарное двухсловное строение союза.\n\n**Различие контекста:** Пояснение лица внутри предложения; авторская разговорная синтаксическая манера.\n\n**Источник:** d50, вариант 13, предложение 2 (d50-v13-p2).\n\n**Прослеживаемость:** `ege14-raw-36714e0ea756d3b4d7d32d80382b4973c1d308eb9a8c36eba3cda02ba28441ea:1`; `research/stage1/classified_batch_03.json#/records/25/contexts/0`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (НА)СПЕХ → наспех. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Примечание:** Сохранён необычный, но связный исходный синтаксис «что записывал, а что и не записывал». Пересказ вместо оригинала не выполнен.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N10: Решения преподавателя](../teacher_decisions.md).",
