        "sourceMarkdown": "### C09-09 — по тому\n\n(ПО)ТОМУ, насколько в стране налажено библиотечное дело, можно судить об уровне общей культуры.\n\n**Нормативное написание:** по тому. **Тип:** раздельно.\n\n**Грамматика:** Предлог по + указательное местоимение тому в дательном падеже; контрольный омоним, не союз.\n\n**Объяснение:** Судить по чему? — по тому, насколько налажено библиотечное дело. По управляет местоимением, а придаточная часть раскрывает указание. Сочетание называет основание оценки; это не причинный союз потому что.\n\n**Дистрактор C09.E:** Считать любую последовательность по/тому началом причинного союза. Правильная стратегия: Проверить управление по чему и местоименное указание; не переносить написание потому что на свободное по тому.\n\n**Различие контекста:** Вывод об общественном явлении по наблюдаемому признаку.\n\n**Источник:** d50, вариант 37, предложение 4 (d50-v37-p4).\n\n**Прослеживаемость:** `ege14-raw-1e5937dc3d8c8588b3a6f49b6c254734b09cc1048e8413b43e9db90cacc631a7:5`; `research/stage1/classified_batch_01_v2.json#/records/8/contexts/4`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (НА)СКОЛЬКО → насколько. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Примечание:** Перекрёстный пример из модели местоименных слов: включён только как контраст к потому что; отдельный блок наречий не создаётся.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N10: Решения преподавателя](../teacher_decisions.md).",
