        "sourceMarkdown": "### C09-10 — по тому\n\n(ПО)ТОМУ, как этот человек держится, видно, что он во всём привык быть первым.\n\n**Нормативное написание:** по тому. **Тип:** раздельно.\n\n**Грамматика:** Предлог по + указательное местоимение тому в дательном падеже; не союз.\n\n**Объяснение:** Видно по чему? — по тому, как человек держится. Местоимение входит в зависимую предложную группу, а придаточная часть раскрывает наблюдаемый признак. Предлог по пишется отдельно, хотя сочетание стоит в начале сложного предложения.\n\n**Дистрактор C09.E:** Считать любую последовательность по/тому началом причинного союза. Правильная стратегия: Проверить управление по чему и местоименное указание; не переносить написание потому что на свободное по тому.\n\n**Различие контекста:** Вывод о характере по манере держаться.\n\n**Источник:** d36, вариант 18, предложение 1 (d36-v18-p1).\n\n**Прослеживаемость:** `ege14-raw-1e5937dc3d8c8588b3a6f49b6c254734b09cc1048e8413b43e9db90cacc631a7:9`; `research/stage1/classified_batch_01_v2.json#/records/8/contexts/8`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (ВО)ВСЁМ → во всём. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Примечание:** Перекрёстный исходный пример для дистрактора C09.E; грамматика по тому не переименована в союз.\n\n**Опора:** [N01: Д. Э. Розенталь. Раздел 16. Правописание союзов](https://old-rozental.ru/orfografia.php?sid=73); [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N10: Решения преподавателя](../teacher_decisions.md).",
