        "sourceMarkdown": "### C10-01 — будто\n\nГрохот невиданного грома как бы рассёк землю надвое, и мне даже показалось, БУД(ТО) она дрогнула.\n\n**Нормативное написание:** будто. **Тип:** слитно.\n\n**Грамматика:** Подчинительный изъяснительный союз со значением предположения.\n\n**Объяснение:** Будто вводит содержание впечатления: показалось, что земля дрогнула. То здесь не самостоятельная частица; слово будто неделимо и пишется без дефиса.\n\n**Дистрактор C10.A:** Писать буд-то/буд то по аналогии с самостоятельной частицей -то. Правильная стратегия: Сохранить словарную цельность будто независимо от союзной или частичной функции.\n\n**Различие контекста:** Изъяснительное придаточное после показалось.\n\n**Источник:** d50, вариант 49, предложение 2 (d50-v49-p2).\n\n**Прослеживаемость:** `ege14-raw-41f75027fbccbd6bf210e8916b2a3561c45ff5231234b557b8f350415800dfaf:3`; `research/stage1/classified_batch_02.json#/records/8/contexts/2`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** КАК(БЫ) → как бы. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N09: Утверждённая корректировка первой партии](../stage1/batch_01_corrections.md).",
