        "sourceMarkdown": "### C10-02 — будто\n\nВ полуразрушенном городе было пустынно, БУД(ТО) всех унёс с собой мощный ураган.\n\n**Нормативное написание:** будто. **Тип:** слитно.\n\n**Грамматика:** Подчинительный сравнительный союз.\n\n**Объяснение:** Союз вводит отдельную предикативную часть с воображаемым объяснением пустоты города. Написание будто словарно цельное; перенос дефиса от кто-то ошибочен.\n\n**Дистрактор C10.A:** Писать буд-то/буд то по аналогии с самостоятельной частицей -то. Правильная стратегия: Сохранить словарную цельность будто независимо от союзной или частичной функции.\n\n**Различие контекста:** Сравнительное придаточное с собственной основой.\n\n**Источник:** d36, вариант 22, предложение 2 (d36-v22-p2).\n\n**Прослеживаемость:** `ege14-raw-41f75027fbccbd6bf210e8916b2a3561c45ff5231234b557b8f350415800dfaf:5`; `research/stage1/classified_batch_02.json#/records/8/contexts/4`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** (ПОЛУ)РАЗРУШЕННОМ → полуразрушенном. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Примечание:** Выбран неповреждённый параллельный контекст вместо d36-v08-p2. Нецелевое полуразрушенном раскрыто слитно; спор о типе его грамматической основы не включён в объяснение союза.\n\n**Опора:** [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N09: Утверждённая корректировка первой партии](../stage1/batch_01_corrections.md).",
