        "sourceMarkdown": "### C10-05 — как будто\n\nЧтобы отвлечься от переживаний, герои повести Льва Кассиля Лёлька и Оська решили поиграть, КАК(БУДТО) они жители неизведанной страны.\n\n**Нормативное написание:** как будто. **Тип:** раздельно.\n\n**Грамматика:** Составной подчинительный сравнительный союз.\n\n**Объяснение:** Сочетание вводит воображаемую ситуацию с собственной основой они жители. Как и будто сохраняются как два слова; изменение союзной функции на частичную в других контекстах на написание не влияет.\n\n**Дистрактор C10.B:** Писать как-будто, какбудто или как буд-то; менять пробел при смене функции. Правильная стратегия: Различить союз и частицу, сохранив два слова как будто и цельное будто.\n\n**Различие контекста:** Воображаемая ситуация в игре.\n\n**Источник:** d50, вариант 35, предложение 2 (d50-v35-p2).\n\n**Прослеживаемость:** `ege14-raw-add4a7812e27b14e3db51907feb23e1bb2df7340cfb7b168eb518080851dfb6e:5`; `research/stage1/classified_batch_01_v2.json#/records/12/contexts/4`. Полный исходный текст, координаты и прежний разбор сохранены в JSON.\n\n**Подготовка текста:** ЧТО(БЫ) → Чтобы. Остальной текст сохранён.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N09: Утверждённая корректировка первой партии](../stage1/batch_01_corrections.md).",
