        "sourceMarkdown": "### C11-02 — хотя бы\n\nМы вернёмся к рукописи, ХОТЯ(БЫ) на проверку одного фрагмента пришлось потратить целый месяц.\n\n**Нормативное написание:** хотя бы. **Тип:** раздельно.\n\n**Грамматика:** Составной уступительный союз с условным оттенком.\n\n**Объяснение:** Придаточная часть допускает даже неблагоприятное условие — долгую проверку, которое не отменяет возвращения к рукописи. Союзное сочетание хотя бы состоит из двух слов; бы не сливается с хотя.\n\n**Дистрактор C11.A:** Сливать хотя бы или ставить дефис; объявлять всякое хотя бы союзом. Правильная стратегия: Отдельно определить союзную/частичную функцию; в обеих функциях сохранить два слова.\n\n**Различие контекста:** Уступительное условие после главной части.\n\n**Источник:** авторский.\n\n**Статус:** готов к технической интеграции. Полное предлагаемое предложение прочитано; сверка с печатным оригиналом не заявляется.\n\n**Опора:** [N03: Полный академический справочник, § 142](https://orthographia.ru/orf.php?paragraph=pp142.php); [N05: Русский орфографический словарь: статьи итак, хотя бы](https://gramota.ru/storage/public/normdicts/orfograficheskij_slovar.pdf); [N07: Грамота.ру. Справочник по пунктуации: «Хотя бы»](https://gramota.ru/biblioteka/spravochniki/spravochnik-po-punktuatsii/khotya-by).",
